    { type: 'essay', q: 'علل: تطاير سقوف الأبنية المصنوعة من صفائح الألمنيوم في الأعاصير.', modelAnswer: 'لأن سرعة الهواء اعلى السقوف يجعل الضغط يقل حسب قاعدة برنولي إذ أن التناسب بين الضغط والسرعة عكسي. أما اسفل السقف يبقى الضغط الجوي فيتغلب الضغط اسفل السقف على الضغط الخارجي فيؤدي الى اقتلاعها تم تتطاير بفعل الرياح.' },
    { type: 'essay', q: 'علل: يتألم السابح الحافي من الشاطئ الخشن ويقل ألمه كلما تغلغل في الماء.', modelAnswer: 'وذلك لأن وزنه يقل كلما تغلغل في الماء بسبب (قوة الطفو) القوة الصعودية للماء التي تقلل من وزنه فيكون ضغطه على السطح الخشن قليل.' }
