  questions: [
    { type: 'essay', q: 'علل: البعد البؤري لعدسة يختلف باختلاف لون الضوء الساقط عليها.', modelAnswer: 'لأن العدسة بعض الشبه بالموشور. فعند سقوط الضوء الابيض عليها فانه يتشتت فالضوء البنفسجي ينكسر فيها أكثر من بقية الالوان ويتجمع في بؤرة أقصر من ابعاد بقية البؤر التي تتجمع فيها بقية الالوان. وهذا يعني ان الضوء الاحمر الذي انكساره في العدسة أقل من بقية الالوان سيتجمع في بؤره بعدها عن العدسة أكبر من ابعاد بؤرة الالوان الأخرى.' },
    { type: 'essay', q: 'علل: تغير البعد البؤري للعدسة اللامة عند نقلها من الهواء الى الماء.', modelAnswer: 'العدسة اللامة الرقيقة تكسر الاشعة المتوازية لتجعلها تلتقي في بؤرة الاساسية الا ان البؤرة الواقعة على المحور الاساسي يعتمد موضعها على معامل الانكسار النسبي بين الوسطين (للعدسة والهواء) فعند نقلها للماء يقل معامل الانكسار النسبي وهذا النقصان في معامل الانكسار النسبي يجعل البعد البؤري أبعد مما لو كان في الهواء.' },
    { type: 'essay', q: 'علل: الموشور ذو الزاوية الرأس الاكبر يحرف الاشعة الضوئية النافذة فيه نحو قاعدته أكثر من الموشور ذي زاوية الرأس الاصغر.', modelAnswer: 'كلما زادت زاوية الرأس زاد ميل الموشور وبالتالي زادت زاوية الانحراف (انحراف الاشعة) كذلك زيادة ميل الموشور يجعل زاوية السقوط كذلك تكبر زاوية النفوذ فيكون زاوية الانحراف كبيرة.' },
    { type: 'essay', q: 'علل: الاشعة الضوئية التي تمر بالمركز البصري للعدسات الرقيقة تنفذ من العدسة بنفس الاتجاه.', modelAnswer: 'والسبب ان جانبي العدسة عند المركز البصري متوازيان تقريبا، مع كون العدسة رقيقة، فيكون الشعاع النافذ بنفس الاتجاه او مزاح قليلا جدا يمكن اهماله بسبب كون العدسة رقيقة.' }
  ]
